reps=[]
def add(a,b,item,edits):
 old='\n'.join(lines[a-1:b]); new=old
 for x,y in edits:
  assert x in new,(a,x)
  new=new.replace(x,y)
 assert text.count(old)==1
 reps.append(dict(old=old,new=new,item=item,source_location=f'paper_v4.Rmd:{a}-{b}'))
add(693,693,11,[('The 2003, 2004, and 2005 estimates are smaller than the 2009 rank-one estimate;', 'The 2003, 2004, and 2005 estimates are smaller in absolute value than the 2009 rank-one estimate;'),('These are point-estimate diagnostics rather than additional tests with separately recomputed placebo inference.', 'Each row refits the SDiD counterfactual over a different pre- or post-onset window. The early estimates average 2003--2008, 2004--2008, and 2005--2008, compared with 2009--2015 for the preferred estimate and 2012--2016 for the later break. Their ordering is suggestive timing evidence, not a comparison of a common estimand or a test that the effects differ. No uncertainty for differences between rows is reported, and the 2012 fit uses already-treated years in its nominal pre-period.')])
add(695,695,11,[('If that ideological shift were sufficient to explain Brazil-China UNGA convergence, the pseudo-treatment years in 2003 or 2005 should already show comparable movement. They do not.', 'The 2003 and 2005 pseudo-onsets yield smaller point estimates in absolute value, providing suggestive evidence against an immediate large break. Because these estimates cover different periods and refit the counterfactual, they do not establish that the early and 2009 effects differ or exclude a gradual or delayed Lula-era shift.')])
add(756,756,11,[('estimates that are stable across the Brazil timing tests, donor-pool checks, and the cross-country duration and risk-set checks.', 'estimates that are stable across the donor-pool checks and the cross-country duration and risk-set checks, alongside the suggestive Brazil timing diagnostics.')])
add(526,526,11,[('E. Windows and timing: stability of the point estimate','E. Windows and timing: point-estimate diagnostics')])
add(530,541,11,[('"and all sensitivity results appear in the appendix."','"and all sensitivity results appear in the appendix. The 2004 and 2009 onset rows use different ",\n      "pre- and post-onset periods and separately fitted counterfactuals; their ordering is suggestive ",\n      "and does not establish a statistically significant difference between effects."')])
add(773,783,11,[('ATT is the estimated causal effect on Brazil after the nominal onset, so negative values mean convergence','ATT denotes the SDiD estimate for Brazil after each nominal onset; negative values indicate convergence'),('2003-2005 timing tests end in 2008; 2012 is a later-break falsification using data through 2016','all windows begin in 1997. Post-onset periods are 2003-2008, 2004-2008, 2005-2008, 2009-2015, and 2012-2016 (6, 5, 4, 7, and 5 years)'),('All rows are no-covariate point-estimate diagnostics. The preferred 2009 estimate and its inference are reported separately in the main specification.','All rows use Brazil and the same 95 donors, without covariates, but refit unit and time weights for each window and onset. These are suggestive diagnostics with different estimands, not tests of differences between effects; no uncertainty for the cross-row contrasts is reported. The 2012 nominal pre-period includes already-treated years. The preferred 2009 estimate and its inference are reported separately in the main specification.')])
add(2239,2240,22,[('its IFE estimate is materially smaller and less precise under UNGA-DM.', 'its IFE point estimate is closer to zero on the UNGA-DM scale and its uncertainty interval includes zero.'),('so the contribution of factor selection can be assessed separately from the outcome-source difference.', 'allowing conditional factor-count comparisons within each measure. It does not provide a unique, scale-invariant decomposition of the difference between outcomes.')])
add(2417,2419,22,[('The estimate retains the negative sign but is smaller and less precise under UNGA-DM:', 'The estimate retains the negative sign but is closer to zero on the UNGA-DM scale, with an uncertainty interval that includes zero:'),('allowing the factor-count component to be assessed separately.', 'allowing the sensitivity to factor count to be assessed within each outcome measure, rather than uniquely decomposing the cross-outcome difference.')])
add(2461,2461,22,[('This $2\\times2$ design isolates the factor-count component of the comparison.', 'This $2\\times2$ comparison describes sensitivity to factor count conditional on the outcome measure.'),('The one-factor UNGA-DM fit selected by cross-validation has the same negative sign and substantially overlapping uncertainty with the fixed-two-factor fit, although its point estimate is less negative; factor selection therefore changes magnitude without reversing the qualitative pattern.', 'The change from one to two factors differs across the two measures, indicating a descriptive interaction between outcome source and factor count rather than a unique additive decomposition. This comparison does not test the interaction. Both UNGA-DM fits have negative point estimates and uncertainty intervals that include zero; overlapping intervals do not establish equivalence.'),('so the outcome source remains relevant after the factor-count component is isolated.', 'but these raw estimates are expressed on different outcome scales. Their difference is a conditional sensitivity comparison, not a scale-invariant contribution attributable to outcome source.')])
add(2447,2454,22,[('" bootstrap replications."','" bootstrap replications. ATTs and intervals are expressed on each outcome\'s original scale; ",\n      "raw cross-outcome differences do not identify a scale-invariant measurement contribution."')])
add(2489,2500,22,[('"Paired bootstrap on the difference between the two ATTs, "','"Paired bootstrap on UNGA-DM minus BSV in their original outcome units, "'),('") under procedure-selected factor counts, and "','") with the original CV-selected counts held fixed (BSV: two; UNGA-DM: one), and "'),('") with common factors."','") with two factors for both outcomes. The same stratified country draws are used for both ",\n      "measures; factor counts are not reselected within replications. These are scale-dependent ",\n      "contrasts, not a unique decomposition of factor and outcome-source components. ",\n      "Non-rejection does not establish equivalence."')])
add(2507,2507,22,[('while the one-factor choice selected by cross-validation for UNGA-DM remains qualitatively close to the two-factor fit, with the same sign and overlapping uncertainty.', 'with a different within-measure change under BSV and UNGA-DM. Both UNGA-DM fits have negative point estimates and uncertainty intervals that include zero; this does not establish equivalence between them.'),('Even with two factors held fixed, the UNGA-DM estimate remains smaller than the BSV estimate, so the outcome metric contributes beyond factor selection.', 'Even with two factors held fixed, the raw UNGA-DM estimate is closer to zero than the BSV estimate on its own scale. This conditional comparison does not isolate a scale-invariant outcome-source contribution beyond factor selection.')])
